import random
from collections import deque

def bfs_dist(adj, s, t, limit):
    # BFS distance between s and t up to limit
    if s == t: return 0
    dist = {s: 0}
    q = deque([s])
    while q:
        u = q.popleft()
        if dist[u] >= limit: continue
        for v in adj[u]:
            if v not in dist:
                dist[v] = dist[u]+1
                if v == t: return dist[v]
                q.append(v)
    return float('inf')

def try_build(n=25, target_edges=36, seed=0):
    random.seed(seed)
    adj = {i:set() for i in range(n)}
    edges = []
    pairs = [(i,j) for i in range(n) for j in range(i+1,n)]
    random.shuffle(pairs)
    for (u,v) in pairs:
        # adding edge u-v creates a cycle of length 1 + dist(u,v) in current graph
        # need cycle length >= 7, so dist(u,v) >= 6 or infinity
        d = bfs_dist(adj, u, v, 6)
        if d >= 6:
            adj[u].add(v); adj[v].add(u)
            edges.append((u,v))
            if len(edges) >= target_edges: break
    return edges, adj

