# Compute girth via BFS from each vertex
from collections import deque
def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = {s:0}
        parent = {s:-1}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    c = dist[u]+dist[v]+1
                    if c < g: g = c
    return g

