color = [-1]*n
def backtrack(i):
    if i == n: return True
    v = deg_order[i]
    used = {color[u] for u in adj[v] if color[u]>=0}
    for c in range(5):
        if c not in used:
            color[v]=c
            if backtrack(i+1): return True
            color[v]=-1
